import sys, json
baseline = json.load(open('baseline-packages.json'))
after = json.loads(sys.stdin.read())

def extract(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            for pkg in fw.get('topLevelPackages', []):
                result[(name, pkg['id'])] = pkg['resolvedVersion']
    return result

b = extract(baseline)
a = extract(after)
changes = []
for k in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(k)
    av = a.get(k)
    if bv != av:
        changes.append(f'{k[0]} | {k[1]} | {bv} -> {av}')
if changes:
    for c in changes: print(c)
else:
    print('No version changes - fully version-neutral')
